"""cu.sub_ps representative candidate emitter (docs/37).

16x16: dst = (int16)src0 - (int16)src1 per pixel, SVE 16-lane rows.
"""


def emit(func_name="dynopt_cu_sub_ps_16x16_sve2"):
    return """\
// Generated by tools/emit_cu_sub_ps_sve2_shared.py -- do not edit.
#include <arm_sve.h>
#include <stdint.h>
#include <stddef.h>

extern "C" void %s(int16_t* dst, intptr_t dstStride,
                   const uint8_t* src0, const uint8_t* src1,
                   intptr_t s0st, intptr_t s1st)
{
    const svbool_t p16 = svptrue_b16();
    for (int r = 0; r < 16; r++)
    {
        const svint16_t a = svld1ub_s16(p16, src0 + r * s0st);
        const svint16_t b = svld1ub_s16(p16, src1 + r * s1st);
        svst1_s16(p16, dst + r * dstStride, svsub_s16_x(p16, a, b));
    }
}
""" % func_name


def emit_combo(combo):
    return emit()
